/*
 * softfloat.c -- software IEEE-754 arithmetic for MIPS targets built with
 * -msoft-float.  Provides the libgcc floating point helper routines
 * (__adddf3 & friends) using integer arithmetic only, so the code runs on
 * machines/emulators without an FPU.
 *
 * binary64 is implemented natively; binary32 operations are performed in
 * binary64 and rounded to binary32 (single rounding step for +,-,* of
 * normal values, at most 1ulp double-rounding error for /).
 */

typedef unsigned int u32;
typedef int s32;
typedef unsigned long long u64;
typedef long long s64;

#ifdef SF_TEST
#define SFN(x) sf_##x
#else
#define SFN(x) x
#endif

#define DSIGN  ((u64)1 << 63)
#define DMANT  ((((u64)1) << 52) - 1)
#define DBIT52 (((u64)1) << 52)
#define DNAN   0x7ff8000000000000ULL
#define FNAN   0x7fc00000u

static u64 dbits(double x) { union { double d; u64 u; } v; v.d = x; return v.u; }
static double dfrom(u64 u) { union { double d; u64 u; } v; v.u = u; return v.d; }
static u32 fbits(float x) { union { float f; u32 u; } v; v.f = x; return v.u; }
static float ffrom(u32 u) { union { float f; u32 u; } v; v.u = u; return v.f; }

static double dinf(int sign) { return dfrom((sign ? DSIGN : 0) | ((u64)0x7ff << 52)); }
static float finf(int sign) { return ffrom((sign ? 0x80000000u : 0) | (255u << 23)); }

/* right shift with sticky bit preservation */
static u64 shr_sticky(u64 m, int d)
{
    u64 st;
    if (d <= 0)
        return m;
    if (d > 63)
        return m != 0;
    st = (m & ((((u64)1) << d) - 1)) != 0;
    return (m >> d) | st;
}

/* Build a double from value = m * 2^(exp-1078), round to nearest even. */
static double dpack(int sign, int exp, u64 m)
{
    u64 r;

    if (m == 0)
        return dfrom(sign ? DSIGN : 0);

    while (m >= (((u64)1) << 56)) {
        u64 s = m & 1;
        m >>= 1;
        m |= s;
        exp++;
    }
    while (m < (((u64)1) << 55) && exp > 1) {
        m <<= 1;
        exp--;
    }
    if (exp < 1) {
        m = shr_sticky(m, 1 - exp);
        exp = 1;
        if (m == 0)
            return dfrom(sign ? DSIGN : 0);
    }

    r = m & 7;
    m >>= 3;
    if (r > 4 || (r == 4 && (m & 1)))
        m++;
    if (m >= (((u64)1) << 53)) {
        m >>= 1;
        exp++;
    }
    if (m < DBIT52)                     /* subnormal result (exp == 1) */
        return dfrom((sign ? DSIGN : 0) | m);
    if (exp >= 2047)
        return dinf(sign);
    return dfrom((sign ? DSIGN : 0) | ((u64)exp << 52) | (m & DMANT));
}

/* Build a float from value = m * 2^(exp-153), round to nearest even. */
static float fpack(int sign, int exp, u64 m)
{
    u64 r;
    u32 s = sign ? 0x80000000u : 0;

    if (m == 0)
        return ffrom(s);

    while (m >= (((u64)1) << 27)) {
        u64 t = m & 1;
        m >>= 1;
        m |= t;
        exp++;
    }
    while (m < (((u64)1) << 26) && exp > 1) {
        m <<= 1;
        exp--;
    }
    if (exp < 1) {
        m = shr_sticky(m, 1 - exp);
        exp = 1;
        if (m == 0)
            return ffrom(s);
    }

    r = m & 7;
    m >>= 3;
    if (r > 4 || (r == 4 && (m & 1)))
        m++;
    if (m >= (((u64)1) << 24)) {
        m >>= 1;
        exp++;
    }
    if (m < (((u64)1) << 23))
        return ffrom(s | (u32)m);
    if (exp >= 255)
        return finf(sign);
    return ffrom(s | ((u32)exp << 23) | ((u32)m & 0x7fffffu));
}

static void mul64(u64 a, u64 b, u64 *hi, u64 *lo)
{
    u32 a0 = (u32)a, a1 = (u32)(a >> 32);
    u32 b0 = (u32)b, b1 = (u32)(b >> 32);
    u64 p00 = (u64)a0 * b0;
    u64 p01 = (u64)a0 * b1;
    u64 p10 = (u64)a1 * b0;
    u64 p11 = (u64)a1 * b1;
    u64 mid = (p00 >> 32) + (u64)(u32)p01 + (u64)(u32)p10;

    *lo = (((u64)(u32)mid) << 32) | (u32)p00;
    *hi = p11 + (p01 >> 32) + (p10 >> 32) + (mid >> 32);
}

static double dadd(double a, double b, int negate_b)
{
    u64 ua = dbits(a), ub = dbits(b);
    int sa = (int)(ua >> 63);
    int sb = (int)(ub >> 63) ^ (negate_b ? 1 : 0);
    int ea = (int)((ua >> 52) & 0x7ff);
    int eb = (int)((ub >> 52) & 0x7ff);
    u64 ma = ua & DMANT, mb = ub & DMANT;

    if (ea == 0x7ff) {
        if (ma)
            return dfrom(DNAN);
        if (eb == 0x7ff) {
            if (mb)
                return dfrom(DNAN);
            if (sa != sb)
                return dfrom(DNAN);
        }
        return dinf(sa);
    }
    if (eb == 0x7ff) {
        if (mb)
            return dfrom(DNAN);
        return dinf(sb);
    }

    if (ea)
        ma |= DBIT52;
    else
        ea = 1;
    if (eb)
        mb |= DBIT52;
    else
        eb = 1;

    if (ma == 0 && mb == 0)
        return dfrom((u64)(sa & sb) << 63);

    ma <<= 3;
    mb <<= 3;

    if (ea > eb) {
        mb = shr_sticky(mb, ea - eb);
        eb = ea;
    } else if (eb > ea) {
        ma = shr_sticky(ma, eb - ea);
        ea = eb;
    }

    if (sa == sb)
        return dpack(sa, ea, ma + mb);
    if (ma == mb)
        return dfrom(0);
    if (ma > mb)
        return dpack(sa, ea, ma - mb);
    return dpack(sb, ea, mb - ma);
}

static double dmul(double a, double b)
{
    u64 ua = dbits(a), ub = dbits(b);
    int sa = (int)(ua >> 63), sb = (int)(ub >> 63);
    int ea = (int)((ua >> 52) & 0x7ff);
    int eb = (int)((ub >> 52) & 0x7ff);
    u64 ma = ua & DMANT, mb = ub & DMANT;
    int sr = sa ^ sb;
    u64 hi, lo, m;

    if (ea == 0x7ff) {
        if (ma)
            return dfrom(DNAN);
        if (eb == 0 && mb == 0)
            return dfrom(DNAN);
        if (eb == 0x7ff && mb)
            return dfrom(DNAN);
        return dinf(sr);
    }
    if (eb == 0x7ff) {
        if (mb)
            return dfrom(DNAN);
        if (ea == 0 && ma == 0)
            return dfrom(DNAN);
        return dinf(sr);
    }

    if (ea)
        ma |= DBIT52;
    else
        ea = 1;
    if (eb)
        mb |= DBIT52;
    else
        eb = 1;

    if (ma == 0 || mb == 0)
        return dfrom((u64)sr << 63);

    while (ma < DBIT52) { ma <<= 1; ea--; }
    while (mb < DBIT52) { mb <<= 1; eb--; }

    mul64(ma, mb, &hi, &lo);
    m = (hi << 14) | (lo >> 50);
    if (lo & ((((u64)1) << 50) - 1))
        m |= 1;

    return dpack(sr, ea + eb - 1022, m);
}

static double ddiv(double a, double b)
{
    u64 ua = dbits(a), ub = dbits(b);
    int sa = (int)(ua >> 63), sb = (int)(ub >> 63);
    int ea = (int)((ua >> 52) & 0x7ff);
    int eb = (int)((ub >> 52) & 0x7ff);
    u64 ma = ua & DMANT, mb = ub & DMANT;
    int sr = sa ^ sb;
    u64 q = 0, rem;
    int i;

    if (ea == 0x7ff) {
        if (ma)
            return dfrom(DNAN);
        if (eb == 0x7ff)
            return dfrom(DNAN);
        return dinf(sr);
    }
    if (eb == 0x7ff) {
        if (mb)
            return dfrom(DNAN);
        return dfrom((u64)sr << 63);            /* finite / inf == 0 */
    }

    if (ea)
        ma |= DBIT52;
    else
        ea = 1;
    if (eb)
        mb |= DBIT52;
    else
        eb = 1;

    if (mb == 0) {
        if (ma == 0)
            return dfrom(DNAN);                 /* 0 / 0 */
        return dinf(sr);                        /* x / 0 */
    }
    if (ma == 0)
        return dfrom((u64)sr << 63);

    while (ma < DBIT52) { ma <<= 1; ea--; }
    while (mb < DBIT52) { mb <<= 1; eb--; }

    rem = ma;
    for (i = 0; i < 56; i++) {
        q <<= 1;
        if (rem >= mb) {
            rem -= mb;
            q |= 1;
        }
        rem <<= 1;
    }
    if (rem)
        q |= 1;

    return dpack(sr, ea - eb + 1023, q);
}

/* -2: unordered, -1: a<b, 0: a==b, 1: a>b */
static int dcmp(double a, double b)
{
    u64 ua = dbits(a), ub = dbits(b);
    int ea = (int)((ua >> 52) & 0x7ff), eb = (int)((ub >> 52) & 0x7ff);
    int sa, sb;

    if ((ea == 0x7ff && (ua & DMANT)) || (eb == 0x7ff && (ub & DMANT)))
        return -2;
    if (((ua | ub) & ~DSIGN) == 0)
        return 0;                               /* +-0 == +-0 */
    if ((ua & ~DSIGN) == 0 && (ub & ~DSIGN) == 0)
        return 0;
    sa = (int)(ua >> 63);
    sb = (int)(ub >> 63);
    if (sa != sb)
        return sa ? -1 : 1;
    if ((ua & ~DSIGN) == (ub & ~DSIGN))
        return 0;
    if ((ua & ~DSIGN) > (ub & ~DSIGN))
        return sa ? -1 : 1;
    return sa ? 1 : -1;
}

