double SFN(__adddf3)(double a, double b) { return dadd(a, b, 0); }
double SFN(__subdf3)(double a, double b) { return dadd(a, b, 1); }
double SFN(__muldf3)(double a, double b) { return dmul(a, b); }
double SFN(__divdf3)(double a, double b) { return ddiv(a, b); }
double SFN(__negdf2)(double a) { return dfrom(dbits(a) ^ DSIGN); }

int SFN(__eqdf2)(double a, double b) { return dcmp(a, b) != 0; }
int SFN(__nedf2)(double a, double b) { return dcmp(a, b) != 0; }
int SFN(__ltdf2)(double a, double b) { int c = dcmp(a, b); return c == -2 ? 1 : c; }
int SFN(__ledf2)(double a, double b) { int c = dcmp(a, b); return c == -2 ? 1 : c; }
