int SFN(__cmpdf2)(double a, double b) { int c = dcmp(a, b); return c == -2 ? 1 : c; }

/* ---- binary32 ---- */

double SFN(__extendsfdf2)(float a)
{
    u32 u = fbits(a);
    int sign = (int)(u >> 31);
    int e = (int)((u >> 23) & 0xff);
    u64 m = u & 0x7fffffu;

    if (e == 255)
        return m ? dfrom(DNAN) : dinf(sign);
    if (e)
        m |= ((u64)1) << 23;
    else
        e = 1;
    if (m == 0)
        return dfrom(sign ? DSIGN : 0);
    return dpack(sign, e + 928, m);
}

float SFN(__truncdfsf2)(double a)
{
    u64 u = dbits(a);
    int sign = (int)(u >> 63);
    int e = (int)((u >> 52) & 0x7ff);
    u64 m = u & DMANT;

    if (e == 0x7ff)
        return m ? ffrom(FNAN) : finf(sign);
    if (e)
        m |= DBIT52;
    else
        e = 1;
    if (m == 0)
        return ffrom(sign ? 0x80000000u : 0);
    return fpack(sign, e - 922, m);
}

float SFN(__addsf3)(float a, float b)
{
    return SFN(__truncdfsf2)(dadd(SFN(__extendsfdf2)(a), SFN(__extendsfdf2)(b), 0));
}
float SFN(__subsf3)(float a, float b)
{
    return SFN(__truncdfsf2)(dadd(SFN(__extendsfdf2)(a), SFN(__extendsfdf2)(b), 1));
}
float SFN(__mulsf3)(float a, float b)
{
    return SFN(__truncdfsf2)(dmul(SFN(__extendsfdf2)(a), SFN(__extendsfdf2)(b)));
}
float SFN(__divsf3)(float a, float b)
{
    return SFN(__truncdfsf2)(ddiv(SFN(__extendsfdf2)(a), SFN(__extendsfdf2)(b)));
}
float SFN(__negsf2)(float a) { return ffrom(fbits(a) ^ 0x80000000u); }

int SFN(__eqsf2)(float a, float b) { return dcmp(SFN(__extendsfdf2)(a), SFN(__extendsfdf2)(b)) != 0; }
int SFN(__nesf2)(float a, float b) { return dcmp(SFN(__extendsfdf2)(a), SFN(__extendsfdf2)(b)) != 0; }
int SFN(__ltsf2)(float a, float b) { int c = dcmp(SFN(__extendsfdf2)(a), SFN(__extendsfdf2)(b)); return c == -2 ? 1 : c; }
int SFN(__lesf2)(float a, float b) { int c = dcmp(SFN(__extendsfdf2)(a), SFN(__extendsfdf2)(b)); return c == -2 ? 1 : c; }
int SFN(__gtsf2)(float a, float b) { int c = dcmp(SFN(__extendsfdf2)(a), SFN(__extendsfdf2)(b)); return c == -2 ? -1 : c; }
int SFN(__gesf2)(float a, float b) { int c = dcmp(SFN(__extendsfdf2)(a), SFN(__extendsfdf2)(b)); return c == -2 ? -1 : c; }
int SFN(__unordsf2)(float a, float b) { return dcmp(SFN(__extendsfdf2)(a), SFN(__extendsfdf2)(b)) == -2; }
int SFN(__cmpsf2)(float a, float b) { int c = dcmp(SFN(__extendsfdf2)(a), SFN(__extendsfdf2)(b)); return c == -2 ? 1 : c; }

