double SFN(__floatsidf)(int i)
{
    int s = i < 0;
    u64 m = s ? (u64)(-(s64)i) : (u64)i;
    return dpack(s, 1078, m);
}
double SFN(__floatunsidf)(unsigned int i) { return dpack(0, 1078, (u64)i); }
double SFN(__floatdidf)(s64 i)
{
    int s = i < 0;
