    return dpack(s, 1078, m);
}
double SFN(__floatundidf)(u64 i) { return dpack(0, 1078, i); }

float SFN(__floatsisf)(int i)
{
    int s = i < 0;
    u64 m = s ? (u64)(-(s64)i) : (u64)i;
    return fpack(s, 153, m);
}
float SFN(__floatunsisf)(unsigned int i) { return fpack(0, 153, (u64)i); }
float SFN(__floatdisf)(s64 i)
{
    int s = i < 0;
