/* ---- float -> integer conversions (truncating) ---- */

static u64 dtrunc_mag(double x, int *sign, int *overflow, int bits)
{
    u64 u = dbits(x);
    int e = (int)((u >> 52) & 0x7ff);
    u64 m = u & DMANT;
    int sh;

    *sign = (int)(u >> 63);
    *overflow = 0;

    if (e == 0x7ff) {
        *overflow = 1;
        return 0;
    }
    if (e == 0)
        return 0;                       /* subnormal truncates to zero */
    m |= DBIT52;
    sh = 1075 - e;
    if (sh >= 64)
        return 0;
    if (sh >= 0)
        return m >> sh;
    if (-sh > bits) {
        *overflow = 1;
        return 0;
    }
    return m << (-sh);
}

int SFN(__fixdfsi)(double a)
{
    int sign, ovf;
    u64 m = dtrunc_mag(a, &sign, &ovf, 11);

    if (ovf || m > 0x80000000ULL)
        return sign ? (-2147483647 - 1) : 2147483647;
    if (sign) {
        if (m >= 0x80000000ULL)
            return -2147483647 - 1;
        return -(int)m;
    }
    if (m > 0x7fffffffULL)
        return 2147483647;
    return (int)m;
}

unsigned int SFN(__fixunsdfsi)(double a)
{
    int sign, ovf;
    u64 m = dtrunc_mag(a, &sign, &ovf, 32);

    if (sign)
        return 0;
    if (ovf || m > 0xffffffffULL)
        return 0xffffffffu;
    return (unsigned int)m;
}

s64 SFN(__fixdfdi)(double a)
{
    int sign, ovf;
    u64 m = dtrunc_mag(a, &sign, &ovf, 63);

    if (ovf || m > 0x8000000000000000ULL)
        return sign ? (-0x7fffffffffffffffLL - 1) : 0x7fffffffffffffffLL;
    if (sign) {
        if (m >= 0x8000000000000000ULL)
            return -0x7fffffffffffffffLL - 1;
        return -(s64)m;
    }
    if (m > 0x7fffffffffffffffULL)
        return 0x7fffffffffffffffLL;
    return (s64)m;
}

u64 SFN(__fixunsdfdi)(double a)
{
    int sign, ovf;
    u64 m = dtrunc_mag(a, &sign, &ovf, 64);

    if (sign)
        return 0;
    if (ovf)
        return 0xffffffffffffffffULL;
    return m;
}

int SFN(__fixsfsi)(float a) { return SFN(__fixdfsi)(SFN(__extendsfdf2)(a)); }
unsigned int SFN(__fixunssfsi)(float a) { return SFN(__fixunsdfsi)(SFN(__extendsfdf2)(a)); }
s64 SFN(__fixsfdi)(float a) { return SFN(__fixdfdi)(SFN(__extendsfdf2)(a)); }
u64 SFN(__fixunssfdi)(float a) { return SFN(__fixunsdfdi)(SFN(__extendsfdf2)(a)); }

