static unsigned long long rnd_state = 88172645463325252ULL;
static unsigned long long rnd(void)
{
    rnd_state ^= rnd_state << 13;
    rnd_state ^= rnd_state >> 7;
    rnd_state ^= rnd_state << 17;
    return rnd_state;
}

static double rand_double(void)
{
    union { double d; unsigned long long u; } v;
    int k = rnd() % 8;

    if (k == 0)
        v.d = (double)(long long)(rnd() % 100000) / (double)(1 + rnd() % 1000);
    else if (k == 1)
        v.d = (double)(int)rnd();
    else if (k == 2)
        v.d = 0.0;
    else if (k == 3)
        v.d = (double)(rnd() % 65536) / 65536.0;
    else {
        v.u = rnd();
        /* keep exponent in a sane range so results stay finite */
        v.u = (v.u & ~(0x7ffULL << 52)) | ((unsigned long long)(700 + rnd() % 600) << 52);
    }
    if (rnd() & 1)
        v.d = -v.d;
    return v.d;
}

